const $searchInput=$('#SearchInput');$(function(){const moduleEngine=new Bloodhound({datumTokenizer:function(module){return Bloodhound.tokenizers.whitespace(module.name||'')},queryTokenizer:Bloodhound.tokenizers.whitespace,remote:{url:$searchInput.data('url')+"?q=%QUERY",wildcard:'%QUERY',filter:function(response){return response.data||[]}}});$searchInput.typeahead({highlight:true,minLength:1},{name:'modules',displayKey:'name',source:moduleEngine.ttAdapter(),limit:10,templates:{header:'<h6 class="suggestions-header text-primary mb-0 mx-3 mt-3 pb-2">Menu Items</h6>',suggestion:function(menu){const description=menu.description?menu.description:"";return '<div class="tt-suggestion-wrapper border-bottom"> <a href="'+menu.link+'" class="text-decoration-none d-flex align-items-center px-3 py-2"> <div class="suggestion-icon me-3 text-secondary" style="width: 24px; text-align: center;">'+menu.icon+'</div><div class="suggestion-content"><h6 class="mb-0 fw-semibold text-dark">'+menu.name+'</h6><small class="text-muted d-block">'+description+'</small></div></a></div>'},notFound:'<div class="not-found px-3 py-2"><h6 class="text-primary mb-2">Menu Items</h6><p class="mb-0">No Results Found</p></div>',pending:'<div class="px-3 py-2">Loading...</div>'}}).on('typeahead:render',function(){if(typeof feather!=='undefined'){feather.replace()}})});
